import math

def min_Jumps(d: float, length: float) -> int:
    d = abs(d)
    if d == 0:
        return 0
    if math.isclose(d, length):
        return 1
    if d < length:
        return 2
    # For d > length:
    # If d is an integer multiple of length, return that quotient
    # else, return quotient + 1
    jumps = d / length
    if math.isclose(jumps, round(jumps)):
        return round(jumps)
    else:
        return math.ceil(jumps)

