import re

def anti_shuffle(s):
    # Split into words and spaces, preserving spaces
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            # Keep spaces as is
            result.append(part)
        else:
            # Sort the characters of the word (including trailing punctuation)
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)

